    with open(out, "w", encoding="utf-8") as f:
        f.write('msgid ""\nmsgstr ""\n"Content-Type: text/plain; charset=UTF-8\\n"\n"Language: pl\\n"\n\n')
        for k in sorted(PL):
            f.write("msgid %s\nmsgstr %s\n\n" % (q(k), q(PL[k])))
    print(len(PL), "entries ->", os.path.normpath(out))
